«لوازم خانگی کوچک» که همیشه پرفروش است این ماه 7 روز کمبود داشت در حالی که فروشش ثابت بود. چرا؟ (مدیر انبار و زنجیرهٔ تأمین — پخش لوازم بهداشتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_orders",
      "description": "سفارش‌های خرید: تاریخ ثبت، تاریخ تحویل و تأمین‌کننده",
      "dimensions": [
        "supplier",
        "order"
      ],
      "measures": [
        "lead_time_days"
      ]
    },
    {
      "dataset": "reorder_history",
      "description": "تاریخچهٔ نقطهٔ سفارش و سفارش‌های مجدد",
      "dimensions": [
        "category",
        "date"
      ],
      "measures": [
        "reorder_point",
        "order_qty"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "stockout_days",
      "description": "روزهای کمبود (موجودی صفر برای مشتری)",
      "formula": "تعداد روزهای کمبود در بازه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "supplier_lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "میانگین روز از ثبت سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "stockout_days"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "stockout_days": {
    "prev_month": 0,
    "curr_month": 7,
    "category": "لوازم خانگی کوچک",
    "note": "کمبود فقط همین کالا"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_orders",
    "filters": {
      "supplier": "تأمین‌کنندهٔ A",
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "lead_time_days": {
    "prev_month": 12,
    "curr_month": 25,
    "note": "تأمین‌کنندهٔ A خط تولید این کالا را تغییر داده و زمان تحویل از 12 به 25 روز رسیده؛ نقطهٔ سفارش هنوز روی 12 روز تنظیم است"
  }
}

