موجودی کل انبار دو ماه است 25٪ رشد کرده و مدیر مالی می‌گوید موجودی مازاد است و باید همین ماه با پروموی سراسری تخلیه شود. این نتیجه‌گیری چقدر معتبر است؟ (مدیر انبار و زنجیرهٔ تأمین — پخش مواد غذایی آریا)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_on_hand",
      "description": "روزهای نگهداشت",
      "formula": "میانگین موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی",
    "معیار اصلی ارزیابی: نرخ پوشش سفارش بدون رشد نامتناسب موجودی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "days_on_hand"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "days_on_hand": {
    "prev_month": null,
    "curr_month": null,
