«شوینده و بهداشتی» که همیشه پرفروش است این ماه 5 روز کمبود داشت در حالی که فروشش ثابت بود. چرا؟ (مدیر انبار و زنجیرهٔ تأمین — پخش مواد غذایی آریا)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_orders",
      "description": "سفارش‌های خرید: تاریخ ثبت، تاریخ تحویل و تأمین‌کننده",
      "dimensions": [
        "supplier",
        "order"
      ],
      "measures": [
        "lead_time_days"
      ]
    },
    {
      "dataset": "reorder_history",
      "description": "تاریخچهٔ نقطهٔ سفارش و سفارش‌های مجدد",
      "dimensions": [
        "category",
        "date"
      ],
      "measures": [
        "reorder_point",
        "order_qty"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "stockout_days",
      "description": "روزهای کمبود (موجودی صفر برای مشتری)",
      "formula": "تعداد روزهای کمبود در بازه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "supplier_lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "میانگین روز از ثبت سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "stockout_days"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "stockout_days": {
    "prev_month": 0,
    "curr_month": 5,
    "category": "شوینده و بهداشتی",
    "note": "کمبود فقط همین کالا"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_orders",
    "filters": {
      "supplier": "تأمین‌کنندهٔ A",
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "lead_time_days": {
    "prev_month": 12,
    "curr_month": 25,
    "note": "تأمین‌کنندهٔ A خط تولید این کالا را تغییر داده و زمان تحویل از 12 به 25 روز رسیده؛ نقطهٔ سفارش هنوز روی 12 روز تنظیم است"
  }
}

نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
روزهای نگهداشت موجودی این ماه 23 روز بلندتر شده و پول بیشتری در انبار خوابیده. دقیقاً کجا و چرا؟ (مدیر انبار و زنجیرهٔ تأمین — زنجیرهٔ دارو و ملزومات)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    },
    {
      "dataset": "reorder_history",
      "description": "تاریخچهٔ نقطهٔ سفارش و سفارش‌های مجدد",
      "dimensions": [
        "category",
        "date"
      ],
      "measures": [
        "reorder_point",
        "order_qty"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_on_hand",
      "description": "روزهای نگهداشت",
      "formula": "میانگین موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "holding_cost",
      "description": "هزینهٔ نگهداشت موجودی",
      "formula": "ارزش موجودی × نرخ نگهداشت سالانه",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی",
    "معیار اصلی ارزیابی: نرخ پوشش سفارش بدون رشد نامتناسب موجودی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "days_on_hand"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "days_on_hand": {
    "prev_month": 36,
    "curr_month": 59,
    "change": 23
  }
