این ماه چرخش موجودی بالاتر رفته ولی روزهای کمبود هم زیاد شده. مدیر فروش می‌گوید موجودی را باید کندتر بچرخانیم. درست است؟ (مدیر انبار و زنجیرهٔ تأمین — توزیع قطعات یدکی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    },
    {
      "dataset": "backorder_log",
      "description": "سفارش‌های عقب‌افتاده به تفکیک روز",
      "dimensions": [
        "date",
        "category"
      ],
      "measures": [
        "orders"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "inventory_turnover",
      "description": "چرخش موجودی",
      "formula": "مصرف دوره / میانگین موجودی",
      "unit": "بار در دوره",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "stockout_days",
      "description": "روزهای کمبود (موجودی صفر برای مشتری)",
      "formula": "تعداد روزهای کمبود در بازه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "inventory_turnover",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "turnover": {
    "prev_month": 2.8,
    "curr_month": 3.7
  },
  "by_category": {
    "نوشیدنی": "چرخش از 2.8 به 4.6 (پرومو + تخلیهٔ پایان فصل)",
    "سایر": "ثابت"
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "stockout_days"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "stockout_days": {
    "prev_month": 2,
    "curr_month": 5
  },
  "by_category": {
    "لوازم الکترونیک": "کمبود 3 روز اضافه (پیش‌بینی فروش خطا و تأمین کمتر از نیاز)",
    "سایر": "صفر"
  }
}

