موجودی کل انبار دو ماه است 22٪ رشد کرده و مدیر مالی می‌گوید موجودی مازاد است و باید همین ماه با پروموی سراسری تخلیه شود. این نتیجه‌گیری چقدر معتبر است؟ (مدیر انبار و زنجیرهٔ تأمین — توزیع قطعات یدکی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "days_on_hand",
      "description": "روزهای نگهداشت",
      "formula": "میانگین موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی",
    "معیار اصلی ارزیابی: نرخ پوشش سفارش بدون رشد نامتناسب موجودی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "days_on_hand"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "days_on_hand": {
    "prev_month": null,
    "curr_month": null,
    "status": "محاسبه نشده — مصرف ماهانهٔ قابل اطمینان موجود نیست"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "inventory_levels",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
این ماه چرخش موجودی بالاتر رفته ولی روزهای کمبود هم زیاد شده. مدیر فروش می‌گوید موجودی را باید کندتر بچرخانیم. درست است؟ (مدیر انبار و زنجیرهٔ تأمین — پخش لوازم بهداشتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "inventory_levels",
      "description": "موجودی میانگین و مصرف به تفکیک دسته و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "avg_inventory_m_toman",
        "usage_m_toman"
      ]
    },
    {
      "dataset": "backorder_log",
      "description": "سفارش‌های عقب‌افتاده به تفکیک روز",
      "dimensions": [
        "date",
        "category"
      ],
      "measures": [
        "orders"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "inventory_turnover",
      "description": "چرخش موجودی",
      "formula": "مصرف دوره / میانگین موجودی",
      "unit": "بار در دوره",
      "dimensions": [
        "category",
        "period"
      ]
    },
    {
      "metric": "stockout_days",
      "description": "روزهای کمبود (موجودی صفر برای مشتری)",
      "formula": "تعداد روزهای کمبود در بازه",
      "unit": "روز",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "inventory_turnover",
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
