    "prev_month": 2.8,
    "curr_month": 4.2
  },
  "by_category": {
    "نوشیدنی": "چرخش از 2.8 به 4.6 (پرومو + تخلیهٔ پایان فصل)",
    "سایر": "ثابت"
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "stockout_days"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
